def read_sql(query, params=()):
    with sqlite3.connect(DB_PATH) as conn:
        return pd.read_sql_query(query, conn, params=params)

def table_exists(name):
    df = read_sql("SELECT name FROM sqlite_master WHERE type IN ('table','view') AND name = ?", (name,))
    return not df.empty

def safe_number(value, default=0):
    try:
        return float(value) if pd.notna(value) else default
    except (TypeError, ValueError):
        return default

if DB_PATH is None:
    st.error("Could not find ipl.db. Put it beside app.py or in data/raw/ipl.db.")
    st.code("project/\n├── dashboard/\n│   └── app.py\n└── data/\n    └── raw/\n        └── ipl.db")
    st.stop()

MATCH_VIEW = "v_matches_clean" if table_exists("v_matches_clean") else "matches_clean"
DELIVERY_VIEW = "v_deliveries_clean" if table_exists("v_deliveries_clean") else "deliveries"

matches = read_sql(f"""
    SELECT match_id, season, match_date, city, venue, venue_clean,
           toss_winner, toss_decision, team1, team2, match_winner,
           win_by_runs, win_by_wickets, result, player_of_match
    FROM {MATCH_VIEW}
""") if MATCH_VIEW == "v_matches_clean" else read_sql(f"""
    SELECT match_id, season, match_date, city, venue,
           toss_winner, toss_decision, team1, team2, match_winner,
           win_by_runs, win_by_wickets, result, player_of_match
    FROM {MATCH_VIEW}
""")
if "venue_clean" not in matches.columns:
    matches["venue_clean"] = matches["venue"]

deliveries = read_sql(f"""
    SELECT match_id, season_id, batter, bowler, over_number, ball_number,
           batter_runs, extras, total_runs, player_out, is_wicket, is_wide_ball,
           is_no_ball, innings, batting_team, bowling_team
    FROM {DELIVERY_VIEW}
""")

# Normalize fields without modifying the database.
for col in ["season", "city", "venue_clean", "toss_winner", "toss_decision",
            "team1", "team2", "match_winner", "player_of_match", "result"]:
    if col in matches.columns:
        matches[col] = matches[col].fillna("Unknown").astype(str).str.strip()
matches["season"] = matches["season"].replace({"None": "Unknown", "nan": "Unknown"})
for col in ["batter", "bowler", "batting_team", "bowling_team"]:
    deliveries[col] = deliveries[col].fillna("Unknown").astype(str).str.strip()
for col in ["batter_runs", "extras", "total_runs", "is_wicket", "is_wide_ball", "is_no_ball", "innings"]:
    deliveries[col] = pd.to_numeric(deliveries[col], errors="coerce").fillna(0)
deliveries["season_id"] = pd.to_numeric(deliveries["season_id"], errors="coerce")

# Map each delivery to the season label from the match table.
season_map = matches[["match_id", "season"]].drop_duplicates("match_id")
deliveries = deliveries.merge(season_map, on="match_id", how="left", suffixes=("", "_match"))
deliveries["season"] = deliveries["season"].fillna("Unknown").astype(str)

seasons = sorted([s for s in matches["season"].dropna().unique() if s != "Unknown"])
teams = sorted(set(matches["team1"].dropna()) | set(matches["team2"].dropna()))
players = sorted(set(deliveries["batter"].dropna()) | set(deliveries["bowler"].dropna()))

