def fmt_int(x):
    return f"{int(round(safe_number(x))):,}"

def add_metric_strip(items):
    # Each KPI gets a cricket-themed emblem in the exact spot where Streamlit's
    # empty help/info badge appeared. The explanation is shown inside the card.
    icon_by_label = {
        "Matches in selection": "🏟️",
        "Runs scored": "🏏",
        "Wickets recorded": "🎯",
        "Toss winners also won": "🪙",
        "Matches won chasing": "🏃",
        "Average first-innings runs": "📊",
    }
    cols = st.columns(3)
    for col, (label, value, help_text) in zip(cols, items):
        icon = icon_by_label.get(label, "🏏")
        col.markdown(
            f'<div class="cricket-kpi-card">'
            f'<div class="cricket-kpi-top">'
            f'<div class="cricket-kpi-label">{label}</div>'
            f'<div class="cricket-kpi-icon" aria-hidden="true">{icon}</div>'
            f'</div>'
            f'<div class="cricket-kpi-value">{value}</div>'
            f'<div class="cricket-kpi-help">{help_text}</div>'
            f'</div>',
            unsafe_allow_html=True,
        )



def chart_filter_controls(data, category_col, key, metric_col=None, default_top_n=10):
    """Add independent category and Top-N controls for one chart."""
    if data is None or data.empty or category_col not in data.columns:
        return data
    filtered = data.copy()
    with st.expander("🔎 Filter this chart", expanded=False):
        options = sorted(filtered[category_col].dropna().astype(str).unique().tolist())
        selected = st.multiselect(
            f"Choose {category_col.replace('_', ' ')}",
            options,
            default=[],
            key=f"{key}_categories",
            help="Leave empty to include every category."
        )
        if selected:
            filtered = filtered[filtered[category_col].astype(str).isin(selected)]
        if metric_col and metric_col in filtered.columns and len(filtered) > 1:
            max_n = min(30, len(filtered))
            n = st.slider(
                "Show top N",
                min_value=1,
                max_value=max_n,
                value=min(default_top_n, max_n),
                key=f"{key}_topn"
            )
            filtered = filtered.nlargest(n, metric_col)
    return filtered


def chart_count_note(n):
    return f"Count: {fmt_int(n)} records"

def make_bar(df, x, y, title, x_title=None, y_title=None, color=None, orientation="v"):
    fig = px.bar(
        df, x=x, y=y, title=title, color=color, orientation=orientation,
        color_discrete_sequence=[GOLD]
    )
    fig.update_traces(
        marker_line_color="#FFE17A", marker_line_width=0.7,
        hovertemplate="%{x}: %{y}<extra></extra>"
    )
    fig.update_layout(
        margin=dict(l=18, r=18, t=58, b=18), height=350,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Inter, sans-serif", color="#F3FFF7", size=11),
        xaxis_title=x_title, yaxis_title=y_title,
        title_font_size=15, title_font_color="#FFFFFF",
        showlegend=False, bargap=0.28,
        hoverlabel=dict(bgcolor="#052B24", font_color="white")
    )
    fig.update_xaxes(showgrid=False, zeroline=False, linecolor="rgba(255,220,90,.35)", tickfont_color="#E9F5EC")
    fig.update_yaxes(gridcolor="rgba(210,245,220,.14)", zeroline=False, tickfont_color="#E9F5EC")
    return fig


def style_fig(fig, height=330):
    fig.update_layout(
        margin=dict(l=18, r=18, t=58, b=18), height=height,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Inter, sans-serif", color="#F3FFF7", size=11),
        title_font_size=15, title_font_color="#FFFFFF",
        legend_title_text="", hoverlabel=dict(bgcolor="#052B24", font_color="white")
    )
    fig.update_xaxes(showgrid=False, zeroline=False, linecolor="rgba(255,220,90,.35)", tickfont_color="#E9F5EC")
    fig.update_yaxes(gridcolor="rgba(210,245,220,.14)", zeroline=False, tickfont_color="#E9F5EC")
    return fig


